      growing: { form: '奶黄短毛微焦，双颊电光噼啪，尾尖冒火花。', habit: '对树桩一遍遍放电练到双颊发麻，夜里望着雷云的方向暗下决心。', origin: '夜林里的练电者。', epithet: '练电皮丘', movement: '双颊噼啪放电轰向树桩，尾尖火花溅起', symbol: '树桩、噼啪电光、雷云远影', theme: '电不是天生的，是一天一点练出来的——练到能照亮黑夜。' },
      mature: { form: '奶黄短毛，双颊电光迸发，尾端闪电铮亮。', habit: '第一次放出完整的十万伏特，轰开坏蛋，护住被欺的同伴。', origin: '夜林救伴的电光初成者。', epithet: '十万伏特皮卡丘', movement: '一记十万伏特轰开坏蛋，电光照亮夜路', symbol: '十万伏特、被护住的同伴、亮起的夜', theme: '我的电不再滋滋响——练了无数夜晚，终于能护人了。' },
      legendary: { form: '雷丘形态，身形壮实，金色电光缭绕，尾如闪电。', habit: '立雷云之下电光冲霄，金电绕身，守护想护的人和山林。', origin: '雷云之下的大成者。', epithet: '雷丘 / 电光皮神', movement: '双颊电光迸发，一记电光冲霄震彻山林', symbol: '雷丘形态、金电缭绕、冲霄电光', theme: '成为想成为的样子不难——难的是没忘最初想护住谁。' },
      transcendent: { form: '雷丘形态，金色电光如披风，双颊电囊如小太阳。', habit: '雷雨夜立森林高处电光四射，为小家伙照亮归路，看新一代皮丘满眼崇拜。', origin: '森林暮光里的电光传说。', epithet: '电光传说 / 皮神', movement: '电光四射照亮归家路，对新一代皮丘露出皮神笑', symbol: '森林高处、四射电光、仰望的皮丘', theme: '从怕雷到守雷雨——我的电，照亮每一个夜路的人。' },
