  riolu:         { form: '蓝黑相间的小犬，胸前黑纹。', habit: '能感知波导之力，善良正义，总为弱者挺身而出。', origin: '格斗系宝可梦，波导之力的继承者。', epithet: '利欧路 / 波导勇者', movement: '双掌凝聚波导弹，一发轰出破空而去。', symbol: '胸前黑纹、波导之力、格斗之魂' },

